//! Two concrete original Sys folds over current complete selected CODE_MAPS loans.
//! DATA has no discovery/EOF authority. The existing concrete RawTree host owes both real completions.
use crate::{captured_api_pages as fund,captured_generator_budget::Budget,captured_raw_file::Config,captured_reactive_reads::Failure,captured_allow_annotations::PatternOperation,reactive_raw_policy_pages::RawPolicyPages};
use std::{io,sync::Arc};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Kind{Requirements,StringNames}
impl Kind{pub fn name(self)->&'static str{match self{Self::Requirements=>"sys/requirements",Self::StringNames=>"sys/dx_string_names"}}pub fn metadata(self)->&'static crate::lint::Meta{static REQUIREMENTS:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();static NAMES:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();match self{Self::Requirements=>REQUIREMENTS.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:crate::allow_registry_fields::sys_requirements::SCOPE_MODULE_NAME,rules:crate::allow_registry_fields::sys_requirements::RULES,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree)),Self::StringNames=>NAMES.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:crate::allow_registry_fields::sys_dx_string_names::SCOPE_MODULE_NAME,rules:crate::allow_registry_fields::sys_dx_string_names::RULES,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree))}}}
enum Facts{Requirements(Vec<(String,String)>),StringNames(crate::sys_string_names_policy::Accessors)}
struct Row{relative:String,facts:Facts}
enum Context<'f,'a>{Requirements(crate::sys_requirements_policy::Effects),StringNames(crate::sys_string_names_policy::Accessors,crate::pat::Pat),NativeStringNames(crate::sys_string_names_policy::Accessors,crate::raw_fixture_policy::Pattern<'f,'a>)}
struct Phase{budget:Arc<Budget>,complete:bool}impl Drop for Phase{fn drop(&mut self){if !self.complete{self.budget.keep_failed_scratch()}}}
fn oom(b:&Budget)->Failure{b.deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())}
fn selected(kind:Kind,config:&Config,relative:&str)->bool{!config.policy_path_exempt(kind.name(),kind.metadata().group,relative)}
pub fn collect(pages:&dyn RawPolicyPages,kind:Kind,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<fund::ApiData,Failure>{collect_using(pages,kind,config,root,poll,None)}
#[cfg(feature="native-policy")]
pub fn collect_with_patterns(pages:&dyn RawPolicyPages,kind:Kind,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<fund::ApiData,Failure>{collect_using(pages,kind,config,root,poll,Some(patterns))}
fn collect_using(pages:&dyn RawPolicyPages,kind:Kind,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<fund::ApiData,Failure>{fund::checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|_|oom(root))?,complete:false};let b=&phase.budget;let context_fixture=patterns.map(|provider|crate::raw_fixture_policy::Fixture::native_patterns(b,poll,provider));let pending=(||{
 let mut facts=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(kind,config,relative){return Ok(true)}let file=views.source_file()?;if relative!=file.rel{return Err("cross Sys original index path differs".into())}let mut retained=PatternOperation{patterns,budget:b,poll};let mut temporary=PatternOperation{patterns,budget:views.allocation_budget(root),poll};let fixture=patterns.map(|provider|crate::raw_fixture_policy::Fixture::scanned(root,poll,provider,file)).transpose().map_err(pattern_failure)?;let legacy=crate::raw_fixture_policy::Fixture::legacy();let actual=fixture.as_ref().unwrap_or(&legacy);let pending=match kind{Kind::Requirements=>crate::sys_requirements_policy::effects_of_using_with_fixture(file,&mut retained,&mut temporary,actual).map(Facts::Requirements),Kind::StringNames=>crate::sys_string_names_policy::file_accessors(file,&mut retained,&mut temporary).map(Facts::StringNames)};if let Some(error)=actual.take_scan_failure(){return Err(pattern_failure(error))}let value=pending?;if fixture.is_some(){actual.finish_scan().map_err(pattern_failure)?}fund::row(b,poll,&mut facts)?;facts.push(Row{relative:fund::own(b,poll,relative)?,facts:value});fund::checked(views.allocation_budget(root),poll)?;Ok(true)})?{return Err("cross Sys original selected index stopped before EOF".into())}
 b.charge(facts.len().checked_mul(4*std::mem::size_of::<Row>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;facts.sort_by(|a,b|a.relative.cmp(&b.relative));let mut control=PatternOperation{patterns,budget:b,poll};
 let context=match kind{Kind::Requirements=>Context::Requirements(crate::sys_requirements_policy::merge(facts.iter().filter_map(|row|match &row.facts{Facts::Requirements(value)=>Some(value),_=>None}),&mut control)?),Kind::StringNames=>{let accessors=crate::sys_string_names_policy::merge(facts.iter().filter_map(|row|match &row.facts{Facts::StringNames(value)=>Some(value),_=>None}),&mut control)?;if let Some(fixture)=context_fixture.as_ref(){let pending=crate::sys_string_names_policy::call_pattern_with_fixture(&accessors,fixture);if let Some(error)=fixture.take_scan_failure(){return Err(pattern_failure(error))}Context::NativeStringNames(accessors,pending.map_err(Failure::from)?)}else{let pattern=crate::sys_string_names_policy::call_pattern_using(&accessors,&mut control)?;Context::StringNames(accessors,pattern)}}};
 let mut batches=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(kind,config,relative){return Ok(true)}let local=views.allocation_budget(root);let file=views.source_file()?;if relative!=file.rel{return Err("cross Sys original judge path differs".into())}let mut retained=PatternOperation{patterns,budget:b,poll};let mut temporary=PatternOperation{patterns,budget:local,poll};let mut rows=Vec::new();let fixture=patterns.map(|provider|crate::raw_fixture_policy::Fixture::scanned(root,poll,provider,file)).transpose().map_err(pattern_failure)?;let legacy=crate::raw_fixture_policy::Fixture::legacy();let actual=fixture.as_ref().unwrap_or(&legacy);let pending=(||{match &context{Context::Requirements(effects)=>{let found=crate::sys_requirements_policy::judge_using_with_fixture(file,effects,&mut retained,&mut temporary,actual)?;fund::reserve_append(b,poll,&mut rows,found.len())?;for(rule,path,line)in found{fund::checked(b,poll)?;if path!=relative{return Err("cross Sys requirement finding path differs".into())}rows.push((rule,line));}},Context::StringNames(accessors,pattern)=>{if crate::sys_string_names_policy::selected(file.text()){crate::sys_string_names_policy::scan_lines_using(file,accessors,pattern,&mut rows,&mut retained,&mut temporary)?;}}Context::NativeStringNames(accessors,pattern)=>{if crate::sys_string_names_policy::selected(file.text()){crate::sys_string_names_policy::scan_lines_programs_using(file,accessors,pattern,&mut rows,&mut retained,&mut temporary,context_fixture.as_ref().expect("native context owns its same operation fixture"))?;}}}Ok::<_,Failure>(())})();if let Some(error)=context_fixture.as_ref().and_then(|fixture|fixture.take_scan_failure()){return Err(pattern_failure(error))}if let Some(error)=actual.take_scan_failure(){return Err(pattern_failure(error))}pending?;if fixture.is_some(){actual.finish_scan().map_err(pattern_failure)?}let data=crate::captured_sys_fields_pages::record_rows_with_patterns(views,rows,&[],&[],root,poll,patterns)?;fund::row(b,poll,&mut batches)?;batches.push((fund::own(b,poll,relative)?,data));Ok(true)})?{return Err("cross Sys original selected judge stopped before EOF".into())}
 b.charge(batches.len().checked_mul(4*std::mem::size_of::<(String,fund::ApiData)>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;batches.sort_by(|a,b|a.0.cmp(&b.0));let mut data=fund::empty();for(_,batch)in batches{fund::append(&mut data,batch,root,poll)?;}fund::checked(b,poll)?;Ok(data)
})();if matches!(&pending,Err(Failure::Operational(_))){return pending}fund::checked(root,poll)?;phase.complete=pending.is_ok();drop(phase);pending}

fn pattern_failure(actual:crate::derived_selftest_policy::Failure)->Failure{match actual{crate::derived_selftest_policy::Failure::Operational(error)=>Failure::Operational(error),crate::derived_selftest_policy::Failure::Assertion(message)=>message.into()}}
